import{_ as e,o as t,c as s,ag as i}from"./chunks/framework.i8sMDeRW.js";const k=JSON.parse('{"title":"第 2 课：Token、Tokenization 和上下文窗口","description":"","frontmatter":{},"headers":[],"relativePath":"guide/12-llm-engineering/02-token-tokenization-context.md","filePath":"guide/12-llm-engineering/02-token-tokenization-context.md","lastUpdated":1779765503000}'),p={name:"guide/12-llm-engineering/02-token-tokenization-context.md"};function n(l,a,o,h,d,c){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="第-2-课-token、tokenization-和上下文窗口" tabindex="-1">第 2 课：Token、Tokenization 和上下文窗口 <a class="header-anchor" href="#第-2-课-token、tokenization-和上下文窗口" aria-label="Permalink to &quot;第 2 课：Token、Tokenization 和上下文窗口&quot;">​</a></h1><blockquote><p>本课目标：理解 LLM 为什么要把文字切成 token，token 如何影响成本、速度、上下文窗口、Prompt 设计、RAG 和微调。</p></blockquote><hr><h2 id="_1-什么是-token" tabindex="-1">1. 什么是 token？ <a class="header-anchor" href="#_1-什么是-token" aria-label="Permalink to &quot;1. 什么是 token？&quot;">​</a></h2><p>简单说：</p><blockquote><p>token 是模型读文字时用的小块。</p></blockquote><p>这个“小块”可能是：</p><ul><li>一个中文字</li><li>一个英文单词</li><li>一个英文单词的一部分</li><li>一个标点符号</li><li>一个空格</li><li>一段常见字符组合</li></ul><p>例如英文：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I love artificial intelligence.</span></span></code></pre></div><p>可能会被切成类似：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I | love | artificial | intelligence | .</span></span></code></pre></div><p>但也可能是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I | love | artificial | intellig | ence | .</span></span></code></pre></div><p>这取决于模型使用的 tokenizer。</p><p><strong>Tokenizer</strong> 就是“切词器”。</p><hr><h2 id="_2-中文-token-长什么样" tabindex="-1">2. 中文 token 长什么样？ <a class="header-anchor" href="#_2-中文-token-长什么样" aria-label="Permalink to &quot;2. 中文 token 长什么样？&quot;">​</a></h2><p>中文和英文不太一样。</p><p>中文没有天然空格，所以 tokenizer 可能这样切：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我喜欢人工智能</span></span></code></pre></div><p>可能变成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我 | 喜欢 | 人工 | 智能</span></span></code></pre></div><p>也可能变成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我 | 喜 | 欢 | 人 | 工 | 智 | 能</span></span></code></pre></div><p>不同模型切法不同。</p><p>你现在不需要记住具体规则，只要记住：</p><blockquote><p>token 是模型真正看到的文字单位。</p></blockquote><hr><h2 id="_3-tokenization-是什么" tabindex="-1">3. Tokenization 是什么？ <a class="header-anchor" href="#_3-tokenization-是什么" aria-label="Permalink to &quot;3. Tokenization 是什么？&quot;">​</a></h2><p><strong>Tokenization</strong> 就是：</p><blockquote><p>把人类文字切成 token 的过程。</p></blockquote><p>比如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你好，世界！</span></span></code></pre></div><p>经过 tokenization 后，可能变成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你 | 好 | ， | 世界 | ！</span></span></code></pre></div><p>再往后，这些 token 会被转成数字 ID。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你 → 1234</span></span>
<span class="line"><span>好 → 5678</span></span>
<span class="line"><span>， → 42</span></span>
<span class="line"><span>世界 → 91011</span></span>
<span class="line"><span>！ → 99</span></span></code></pre></div><p>模型真正处理的是这些数字。</p><p>所以完整流程是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>人类文字</span></span>
<span class="line"><span>→ 切成 token</span></span>
<span class="line"><span>→ token 变成数字 ID</span></span>
<span class="line"><span>→ 输入模型</span></span></code></pre></div><hr><h2 id="_4-生活类比-切菜" tabindex="-1">4. 生活类比：切菜 <a class="header-anchor" href="#_4-生活类比-切菜" aria-label="Permalink to &quot;4. 生活类比：切菜&quot;">​</a></h2><p>你可以把 tokenization 想成做饭前的切菜。</p><p>你要炒菜，不能把一整根胡萝卜直接丢进锅里。</p><p>你需要先切成片、丝、块。</p><p>LLM 也一样。</p><p>它不能直接吃整篇文章。</p><p>它需要先把文章切成小块。</p><p>这些小块就是 token。</p><blockquote><p>Tokenization 就是给 AI “切菜”。</p></blockquote><hr><h2 id="_5-为什么-token-很重要" tabindex="-1">5. 为什么 token 很重要？ <a class="header-anchor" href="#_5-为什么-token-很重要" aria-label="Permalink to &quot;5. 为什么 token 很重要？&quot;">​</a></h2><p>因为很多 AI 系统都是按 token 计算的。</p><p>它影响：</p><ul><li>成本</li><li>速度</li><li>上下文长度</li><li>记忆范围</li><li>输出长度</li><li>推理速度</li><li>微调数据大小</li></ul><p>很多 API 的计费方式常见是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 token 数 + 输出 token 数</span></span></code></pre></div><p>输入越长，费用越高。</p><p>输出越长，费用也越高。</p><hr><h2 id="_6-什么是上下文窗口" tabindex="-1">6. 什么是上下文窗口？ <a class="header-anchor" href="#_6-什么是上下文窗口" aria-label="Permalink to &quot;6. 什么是上下文窗口？&quot;">​</a></h2><p><strong>上下文窗口</strong>，英文是 <strong>context window</strong>。</p><p>简单说：</p><blockquote><p>模型一次最多能看到多少 token。</p></blockquote><p>比如一个模型的上下文窗口是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>8K tokens</span></span></code></pre></div><p>意思是：</p><blockquote><p>它一次最多能处理大约 8000 个 token。</p></blockquote><p>如果是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>128K tokens</span></span></code></pre></div><p>意思是：</p><blockquote><p>它一次可以处理更长的文章、更多聊天记录、更多代码。</p></blockquote><p>但注意：</p><blockquote><p>上下文窗口不是永久记忆。</p></blockquote><p>它只是“这一次对话中模型眼前能看到的内容”。</p><hr><h2 id="_7-生活类比-桌面大小" tabindex="-1">7. 生活类比：桌面大小 <a class="header-anchor" href="#_7-生活类比-桌面大小" aria-label="Permalink to &quot;7. 生活类比：桌面大小&quot;">​</a></h2><p>把上下文窗口想成你的书桌。</p><p>小书桌只能同时放：</p><ul><li>一本书</li><li>一支笔</li><li>一张纸</li></ul><p>大书桌可以同时放：</p><ul><li>十本书</li><li>电脑</li><li>笔记本</li><li>多份资料</li></ul><p>LLM 的上下文窗口也是这样。</p><p>上下文窗口越大，它一次能“摊开看”的资料越多。</p><p>但如果资料太多，超过桌面大小，就放不下。</p><hr><h2 id="_8-token-和上下文窗口的关系" tabindex="-1">8. Token 和上下文窗口的关系 <a class="header-anchor" href="#_8-token-和上下文窗口的关系" aria-label="Permalink to &quot;8. Token 和上下文窗口的关系&quot;">​</a></h2><p>假设模型上下文窗口是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4096 tokens</span></span></code></pre></div><p>你输入了：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3000 tokens</span></span></code></pre></div><p>那它最多还能输出大约：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1096 tokens</span></span></code></pre></div><p>因为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入 + 输出 ≤ 上下文窗口</span></span></code></pre></div><p>所以如果你把太长的文档直接塞给模型，可能会遇到：</p><ul><li>内容被截断</li><li>回答不完整</li><li>模型忘记前文</li><li>生成空间不够</li></ul><hr><h2 id="_9-为什么中文、英文-token-数不同" tabindex="-1">9. 为什么中文、英文 token 数不同？ <a class="header-anchor" href="#_9-为什么中文、英文-token-数不同" aria-label="Permalink to &quot;9. 为什么中文、英文 token 数不同？&quot;">​</a></h2><p>同样长度的意思，不同语言的 token 数可能不一样。</p><p>英文通常按单词或词片段切。</p><p>中文可能按字、词或词片段切。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I love AI.</span></span></code></pre></div><p>可能很少 token。</p><p>中文：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我喜欢人工智能。</span></span></code></pre></div><p>也可能是几个 token，也可能更多。</p><p>这取决于 tokenizer 的训练方式。</p><p>对产品经理来说，重点不是记住精确数字，而是理解：</p><blockquote><p>不同语言、不同模型，token 成本可能不同。</p></blockquote><hr><h2 id="_10-token-会影响-prompt-设计" tabindex="-1">10. Token 会影响 Prompt 设计 <a class="header-anchor" href="#_10-token-会影响-prompt-设计" aria-label="Permalink to &quot;10. Token 会影响 Prompt 设计&quot;">​</a></h2><p>假设你写了一个很长的 prompt：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个非常专业、非常负责、非常严谨、非常有耐心、非常细致、非常……</span></span></code></pre></div><p>这会占用很多 token。</p><p>有时候你可以简化成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个严谨、耐心的 AI 教师。</span></span></code></pre></div><p>意思差不多，但更省 token。</p><p>好的 prompt 不一定越长越好。</p><p>好的 prompt 是：</p><blockquote><p>信息清楚，结构合理，不浪费 token。</p></blockquote><hr><h2 id="_11-token-会影响-rag" tabindex="-1">11. Token 会影响 RAG <a class="header-anchor" href="#_11-token-会影响-rag" aria-label="Permalink to &quot;11. Token 会影响 RAG&quot;">​</a></h2><p>RAG 是让 AI 先从资料库里找相关资料，再回答。</p><p>问题是：</p><blockquote><p>找出来的资料也要占 token。</p></blockquote><p>如果你一次塞太多资料进去，模型会读得慢、贵，甚至忽略重点。</p><p>所以做 RAG 时要学会：</p><ul><li>文档切块</li><li>控制 chunk 大小</li><li>只取最相关内容</li><li>去掉重复内容</li><li>压缩上下文</li></ul><p>这些都和 token 有关。</p><hr><h2 id="_12-token-会影响微调" tabindex="-1">12. Token 会影响微调 <a class="header-anchor" href="#_12-token-会影响微调" aria-label="Permalink to &quot;12. Token 会影响微调&quot;">​</a></h2><p>微调时，训练数据也会被切成 token。</p><p>训练成本常常和 token 数有关。</p><p>如果你的训练数据里有很多废话，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>您好您好您好您好您好您好……</span></span></code></pre></div><p>或者大量重复模板，就会浪费训练成本。</p><p>所以微调前要做数据清洗。</p><p>这也是为什么后面要讲：</p><ul><li>dataset cleaning</li><li>dataset formatting</li><li>data curation</li></ul><hr><h2 id="_13-小代码示例-粗略估算-token" tabindex="-1">13. 小代码示例：粗略估算 token <a class="header-anchor" href="#_13-小代码示例-粗略估算-token" aria-label="Permalink to &quot;13. 小代码示例：粗略估算 token&quot;">​</a></h2><p>不同模型有不同 tokenizer。</p><p>但初学时可以先粗略估算：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">text </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;我想学习大语言模型微调。&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 非严格估算：中文可以先粗略按字数估</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rough_tokens </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(text)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rough_tokens)</span></span></code></pre></div><p>这不是精确结果。</p><p>只是帮助你先建立直觉：</p><blockquote><p>文本越长，token 越多，成本越高，占用上下文越多。</p></blockquote><p>以后真正做工程时，要用对应模型的 tokenizer 来算。</p><hr><h2 id="_14-token、字、词的区别" tabindex="-1">14. Token、字、词的区别 <a class="header-anchor" href="#_14-token、字、词的区别" aria-label="Permalink to &quot;14. Token、字、词的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>简单解释</th><th>例子</th></tr></thead><tbody><tr><td>字符</td><td>最小文字单位</td><td>我、A、！</td></tr><tr><td>词</td><td>人类理解的词语</td><td>人工智能、模型</td></tr><tr><td>token</td><td>模型使用的小块</td><td>可能是字、词、词的一部分</td></tr><tr><td>token ID</td><td>token 对应的数字</td><td>“AI” → 12345</td></tr></tbody></table><p>一句话：</p><blockquote><p>人看词，模型看 token，电脑算数字。</p></blockquote><hr><h2 id="_15-对产品经理有什么用" tabindex="-1">15. 对产品经理有什么用？ <a class="header-anchor" href="#_15-对产品经理有什么用" aria-label="Permalink to &quot;15. 对产品经理有什么用？&quot;">​</a></h2><p>你做 AI 产品时，token 很关键。</p><p>它会影响：</p><h3 id="成本设计" tabindex="-1">成本设计 <a class="header-anchor" href="#成本设计" aria-label="Permalink to &quot;成本设计&quot;">​</a></h3><ul><li>用户一次最多上传多少字？</li><li>每次对话允许多长？</li><li>免费用户限制多少 token？</li><li>高级用户给多少上下文？</li></ul><h3 id="体验设计" tabindex="-1">体验设计 <a class="header-anchor" href="#体验设计" aria-label="Permalink to &quot;体验设计&quot;">​</a></h3><ul><li>回答太慢怎么办？</li><li>长文档怎么处理？</li><li>聊天历史太长怎么办？</li><li>是否需要摘要记忆？</li></ul><h3 id="技术方案" tabindex="-1">技术方案 <a class="header-anchor" href="#技术方案" aria-label="Permalink to &quot;技术方案&quot;">​</a></h3><ul><li>用短上下文模型还是长上下文模型？</li><li>用 RAG 还是直接塞全文？</li><li>是否需要压缩 prompt？</li><li>是否需要缓存系统？</li></ul><hr><h2 id="_16-本课总结" tabindex="-1">16. 本课总结 <a class="header-anchor" href="#_16-本课总结" aria-label="Permalink to &quot;16. 本课总结&quot;">​</a></h2><p>Token 是模型读取文字的小块。</p><p>Tokenization 是把文字切成 token 的过程。</p><p>模型不是直接处理文字，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文字 → token → 数字 → 模型计算 → 输出 token → 文字</span></span></code></pre></div><p>Token 影响：</p><ul><li>成本</li><li>速度</li><li>上下文长度</li><li>prompt 设计</li><li>RAG 效果</li><li>微调成本</li><li>部署体验</li></ul><hr><h2 id="_17-心智模型" tabindex="-1">17. 心智模型 <a class="header-anchor" href="#_17-心智模型" aria-label="Permalink to &quot;17. 心智模型&quot;">​</a></h2><p>把 token 想成：</p><blockquote><p>AI 吃进去的一小口食物。</p></blockquote><p>文章太长，就是食物太多。</p><p>上下文窗口就是 AI 的盘子。</p><p>盘子越大，一次能装的食物越多。</p><p>但食物太多也会：</p><ul><li>吃得慢</li><li>花钱多</li><li>消化不好</li><li>忽略重点</li></ul><hr><h2 id="_18-初学者常见错误" tabindex="-1">18. 初学者常见错误 <a class="header-anchor" href="#_18-初学者常见错误" aria-label="Permalink to &quot;18. 初学者常见错误&quot;">​</a></h2><h3 id="错误-1-以为-token-等于字" tabindex="-1">错误 1：以为 token 等于字 <a class="header-anchor" href="#错误-1-以为-token-等于字" aria-label="Permalink to &quot;错误 1：以为 token 等于字&quot;">​</a></h3><p>不一定。</p><p>token 可能是一个字，也可能是一个词，也可能是词的一部分。</p><h3 id="错误-2-以为上下文窗口等于记忆" tabindex="-1">错误 2：以为上下文窗口等于记忆 <a class="header-anchor" href="#错误-2-以为上下文窗口等于记忆" aria-label="Permalink to &quot;错误 2：以为上下文窗口等于记忆&quot;">​</a></h3><p>上下文窗口只是模型当前能看到的内容。</p><p>它不是永久记忆。</p><h3 id="错误-3-prompt-越长越好" tabindex="-1">错误 3：prompt 越长越好 <a class="header-anchor" href="#错误-3-prompt-越长越好" aria-label="Permalink to &quot;错误 3：prompt 越长越好&quot;">​</a></h3><p>不一定。</p><p>长 prompt 可能更贵、更慢，还可能让重点变模糊。</p><h3 id="错误-4-把全文都塞给模型" tabindex="-1">错误 4：把全文都塞给模型 <a class="header-anchor" href="#错误-4-把全文都塞给模型" aria-label="Permalink to &quot;错误 4：把全文都塞给模型&quot;">​</a></h3><p>很多时候应该先筛选、摘要、切块，而不是把所有内容都丢进去。</p><hr><h2 id="_19-小练习" tabindex="-1">19. 小练习 <a class="header-anchor" href="#_19-小练习" aria-label="Permalink to &quot;19. 小练习&quot;">​</a></h2><p>拿下面这句话：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想做一个 AI 客服机器人，帮助用户查询订单和退款。</span></span></code></pre></div><p>试着手动切 token。</p><p>你可以先粗略切成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我 | 想 | 做 | 一个 | AI | 客服 | 机器人 | ， | 帮助 | 用户 | 查询 | 订单 | 和 | 退款 | 。</span></span></code></pre></div><p>然后思考：</p><blockquote><p>如果我要让模型回答得更好，哪些 token 是最重要的？</p></blockquote><p>答案通常是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 客服机器人</span></span>
<span class="line"><span>订单</span></span>
<span class="line"><span>退款</span></span>
<span class="line"><span>用户</span></span>
<span class="line"><span>查询</span></span></code></pre></div><p>这些是语义重点。</p><hr><h2 id="_20-小项目" tabindex="-1">20. 小项目 <a class="header-anchor" href="#_20-小项目" aria-label="Permalink to &quot;20. 小项目&quot;">​</a></h2><p>做一个简单的“prompt 压缩练习”。</p><p>原 prompt：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个非常优秀、非常耐心、非常专业、非常懂人工智能、非常擅长解释复杂概念的老师。请你用非常简单、非常容易理解、非常适合初学者的语言，帮我解释什么是 token 和 tokenization。</span></span></code></pre></div><p>压缩成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是耐心的 AI 老师。用初学者能懂的中文解释 token 和 tokenization。</span></span></code></pre></div><p>对比两个输出。</p><p>你会学到：</p><blockquote><p>好 prompt 不是堆很多形容词，而是清楚表达任务、对象和输出要求。</p></blockquote><hr><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p><a href="./03-embedding-semantic-search.html">第 3 课：Embedding 和语义搜索</a></p>`,222)])])}const u=e(p,[["render",n]]);export{k as __pageData,u as default};
